local function pageBox(page, title, height)
	local S = Build.Section(page.ColumnsData[1].Instance)
	-- the card is 30 px taller than the old flat groupbox (the title row + divider), so the content area keeps its old size
	height = height + 30
	S.Root.AutomaticSize = Enum.AutomaticSize.None
	S.Root.Size = UDim2.new(1, 0, 0, height)
	S.title.Text = title
	S.title.AutomaticSize = Enum.AutomaticSize.X
	S.title.Position, S.title.Size = UDim2.new(), UDim2.new(0, 0, 1, 0)
	S.titleMask.AutomaticSize = Enum.AutomaticSize.X
	S.titleMask.Size = UDim2.new(0, 0, 0, 18)
	S.titleMask.ZIndex, S.title.ZIndex = 3, 4
	S.card.AutomaticSize = Enum.AutomaticSize.None
	S.card.Size, S.card.Position = UDim2.new(1, 0, 0, height), UDim2.new()
	S.content.AutomaticSize = Enum.AutomaticSize.None
	S.content.Position, S.content.Size = UDim2.new(0, 16, 0, 48), UDim2.new(1, -32, 1, -60)
	for _, c in S.content:GetChildren() do if c:IsA("UIListLayout") then c:Destroy() end end
	return S
end

local function fixedFrame(parent, pos, size)
	local f = Instance.new("Frame")
	f.Name = "\0"
	f.BackgroundTransparency = 1
	f.Position, f.Size = pos, size
	f.Parent = parent
	return f
end

local function label(parent, text, pos, size, color, textSize, align)
	local t = Instance.new("TextLabel")
	t.Name = "\0"
	t.BackgroundTransparency = 1
	t.FontFace, t.TextSize = Library.Font, textSize or 12
	t.TextColor3 = color or Library.Theme.Text
	t.TextXAlignment = align or Enum.TextXAlignment.Left
	t.TextTruncate = Enum.TextTruncate.AtEnd
	t.Text = text
	t.Position, t.Size = pos, size
	t.Parent = parent
	return t
end

-- ============================ PlayerList ============================
function Library:PlayerList(Data)
	local page = self
	if page.Columns ~= 1 then
		Library:Notification("Playerlist can only be added to a page with 1 column.", 5, Color3.fromRGB(235, 90, 90))
		return nil
	end
	Data = Data or {}
	local S = pageBox(page, "Players", 419)
	local content = S.content
	local scroll = Instance.new("ScrollingFrame")
	scroll.Name = "\0"
	scroll.BackgroundTransparency, scroll.BorderSizePixel = 1, 0
	scroll.ScrollBarThickness, scroll.ScrollBarImageColor3 = 2, Library.Theme.Inline
	scroll.CanvasSize, scroll.AutomaticCanvasSize = UDim2.new(), Enum.AutomaticSize.Y
	scroll.Position, scroll.Size = UDim2.new(), UDim2.new(1, 0, 0, 315)
	scroll.Parent = content
	Library.listLayout(scroll, 4)

	local DEFAULT_AVATAR = "rbxassetid://98200387761744"
	local avatar = Instance.new("ImageLabel")
	avatar.Name = "\0"
	avatar.BackgroundColor3, avatar.BorderSizePixel = Library.Theme.Element, 0
	avatar.Image = DEFAULT_AVATAR
	avatar.Position, avatar.Size = UDim2.new(0, 0, 0, 325), UDim2.new(0, 70, 0, 70)
	avatar.Parent = content
	Instance.new("UICorner", avatar).CornerRadius = UDim.new(0, 8)
	local userName = label(content, "None", UDim2.new(0, 80, 0, 330), UDim2.new(0.5, -90, 0, 16), Library.Theme.Text)
	local userId = label(content, "None", UDim2.new(0, 80, 0, 350), UDim2.new(0.5, -90, 0, 16), Library.Theme["Dim Text"])

	local pl = { Window = page.Window, Page = page, Player = nil, Players = {}, Items = { Playerlist = Library.Wrap(S.Root) } }

	local STATUS = {
		Neutral = { "Neutral", Color3.fromRGB(180, 180, 180) }, Priority = { "Priority", Color3.fromRGB(255, 50, 50) },
		Friendly = { "Friendly", Color3.fromRGB(83, 255, 83) },
	}
	-- the status dropdown (flag PlayerListPlayerStatus) sits at the bottom right
	local dropHost = fixedFrame(content, UDim2.new(1, -208, 0, 330), UDim2.new(0, 208, 0, 60))
	local fakeSection = { Items = { Content = Library.Wrap(dropHost) }, Window = page.Window, Page = page, Section = nil }
	fakeSection.Section = fakeSection
	local drop = Library.Dropdown(fakeSection, {
		Name = "Status", Flag = "PlayerListPlayerStatus", Items = { "Neutral", "Priority", "Friendly" }, Default = "All", MaxSize = 75,
		Callback = function(value)
			local p = pl.Player
			if not p or p == Players.LocalPlayer then return end
			local rec = pl.Players[p.Name]
			if not rec then return end
			local st = STATUS[value] or STATUS.Neutral
			rec.PlayerStatus.Instance.Text = st[1]
			rec.PlayerStatus.Instance.TextColor3 = st[2]
			if Library.OnPrioritize then pcall(Library.OnPrioritize, p.Name, value) end
		end,
	})
	fakeSection.Items.Content.Instance.Size = UDim2.new(0, 208, 0, 60)

	local function selectedInfo(p)
		if p then
			userName.Text = p.DisplayName .. " (@" .. p.Name .. ")"
			userId.Text = tostring(p.UserId)
			task.spawn(function()
				local ok, img = pcall(function() return Players:GetUserThumbnailAsync(p.UserId, Enum.ThumbnailType.HeadShot, Enum.ThumbnailSize.Size420x420) end)
				if ok and pl.Player == p then avatar.Image = img end
			end)
		else
			avatar.Image = DEFAULT_AVATAR
			userName.Text, userId.Text = "None", "None"
		end
	end

	function pl:Add(player)
		local R = Build.PlayerRow(scroll)
		R.Root.Size = UDim2.new(1, 0, 0, 18)
		R.name.Text = player.Name
		local teamName = player.Team and player.Team.Name or "None"
		R.team.Text = teamName
		R.team.TextColor3 = player.Team and player.TeamColor.Color or Color3.fromRGB(180, 180, 180)
		local isMe = player == Players.LocalPlayer
		R.status.Text = isMe and "LocalPlayer" or "Neutral"
		R.status.TextColor3 = isMe and Library.Theme.Accent or Color3.fromRGB(180, 180, 180)
		R.bg.BackgroundTransparency = 1
		local rec = {
			Name = player.Name, Selected = false, Player = player,
			PlayerButton = Library.Wrap(R.Root), PlayerName = Library.Wrap(R.name), PlayerTeam = Library.Wrap(R.team),
			PlayerStatus = Library.Wrap(R.status), PlayerBackground = Library.Wrap(R.bg),
		}
		function rec:Toggle(mode)
			local active = mode == "Active"
			R.bg.BackgroundTransparency = active and 0 or 1
			R.name.TextColor3 = active and Library.Theme.Accent or Library.Theme.Text
		end
		function rec:Set()
			if rec.Selected then
				rec.Selected = false
				rec:Toggle("Inactive")
				pl.Player = nil
				selectedInfo(nil)
			else
				for _, o in pl.Players do o.Selected = false o:Toggle("Inactive") end
				rec.Selected = true
				rec:Toggle("Active")
				pl.Player = player
				selectedInfo(player)
			end
			if Data.Callback then Library:SafeCall(Data.Callback, pl.Player, rec.PlayerStatus, rec.PlayerTeam) end
		end
		Library.click(R.Root, function() rec:Set() end)
		pl.Players[player.Name] = rec
		return rec
	end
	function pl:Remove(name)
		local rec = pl.Players[name]
		if not rec then return end
		pcall(function() rec.PlayerButton.Instance:Destroy() end)
		if pl.Player and pl.Player.Name == name then pl.Player = nil selectedInfo(nil) end
		pl.Players[name] = nil
	end
	for _, p in Players:GetPlayers() do pl:Add(p) end
	Library:Connect(Players.PlayerAdded, function(p) pl:Add(p) end)
	Library:Connect(Players.PlayerRemoving, function(p) if pl.Players[p.Name] then pl:Remove(p.Name) end end)
	page.PlayerListData = pl
	return pl
end

-- ============================ SkinChanger ============================
local RARITY_RANK = { Stock = 0, Blue = 1, Purple = 2, Pink = 3, Red = 4, Forbidden = 5, Special = 6 }

-- ============================ SkinChanger 3D preview ============================
-- Data.Preview = function(weapon, skin) -> Instance | nil (a fresh model; skin nil = the weapon's default) adds a "Preview" box under the
-- Skin Changer box: the model turns in a ViewportFrame (drag to orbit, wheel / slider to zoom, "auto rotate" toggle). The builder runs in a
-- thread of its own (it may yield), the result is dropped when another item was asked for meanwhile. Data.PreviewHeight (default 280).
local function skinPreview(page, Data)
	local builder = field(Data, "Preview", "preview")
	if type(builder) ~= "function" then return nil end
	local fx = Library.fx
	local S = pageBox(page, "Preview", field(Data, "PreviewHeight", "previewheight") or 280)
	local content = S.content
	local MIN, MAX = 0.5, 3
	local pv = { Zoom = 1, Spin = true, Yaw = 0, Pitch = 0.12, Dragging = false }
	local caption = label(content, "", UDim2.new(), UDim2.new(1, 0, 0, 16), Library.Theme["Dim Text"], 13, Enum.TextXAlignment.Center)
	Library.themed(caption, "TextColor3", "Dim Text")
	-- the view: a dark frame with the viewport in it, a transparent button over it for the mouse
	local frame = Instance.new("Frame")
	frame.Name = "\0"
	frame.BorderSizePixel = 0
	frame.Position, frame.Size = UDim2.fromOffset(0, 20), UDim2.new(1, 0, 1, -48)
	frame.BackgroundColor3 = Library.Theme["Dark Liner"]
	Library.themed(frame, "BackgroundColor3", "Dark Liner")
	frame.ClipsDescendants = true
	frame.Parent = content
	local stroke = Instance.new("UIStroke", frame)
	stroke.Color, stroke.ApplyStrokeMode = Library.Theme.Outline, Enum.ApplyStrokeMode.Border
	Library.themed(stroke, "Color", "Outline")
	local vpf = Instance.new("ViewportFrame")
	vpf.Name = "\0"
	vpf.BackgroundTransparency, vpf.BorderSizePixel = 1, 0
	vpf.Size = UDim2.fromScale(1, 1)
	vpf.Ambient, vpf.LightColor = Color3.fromRGB(165, 165, 165), Color3.new(1, 1, 1)
	vpf.LightDirection = Vector3.new(-0.4, -1, -0.6)
	vpf.Parent = frame
	local cam = Instance.new("Camera")
	cam.FieldOfView = 30
	cam.Parent = vpf
	vpf.CurrentCamera = cam
	local world = Instance.new("WorldModel")
	world.Parent = vpf
	local empty = label(frame, "", UDim2.new(), UDim2.fromScale(1, 1), Library.Theme["Dim Text"], 13, Enum.TextXAlignment.Center)
	Library.themed(empty, "TextColor3", "Dim Text")
	empty.ZIndex = 2

	-- the model: scripts / sounds / animators out, parts anchored, the long axis along X, centred on the origin
	local model, fitDist, halfLen = nil, 6, 2
	local function setModel(m)
		if model then model:Destroy() model = nil end
		if typeof(m) ~= "Instance" then return end
		if not m:IsA("Model") then
			local wrap = Instance.new("Model")
			m.Parent = wrap
			m = wrap
		end
		for _, d in m:GetDescendants() do
			if d:IsA("BaseScript") or d:IsA("Sound") or d:IsA("AnimationController") or d:IsA("Animator") or d:IsA("Humanoid") then d:Destroy()
			elseif d:IsA("BasePart") then d.Anchored, d.CanCollide = true, false end
		end
		-- the box in WORLD axes, from the parts (Model:GetBoundingBox / GetExtentsSize follow the model's own pivot, which turning it does not change)
		local function worldBox()
			local lo, hi = Vector3.new(math.huge, math.huge, math.huge), Vector3.new(-math.huge, -math.huge, -math.huge)
			for _, d in m:GetDescendants() do
				if d:IsA("BasePart") then
					local cf, s = d.CFrame, d.Size
					local r, u, l = cf.RightVector, cf.UpVector, cf.LookVector
					local half = Vector3.new(
						(math.abs(r.X) * s.X + math.abs(u.X) * s.Y + math.abs(l.X) * s.Z) / 2,
						(math.abs(r.Y) * s.X + math.abs(u.Y) * s.Y + math.abs(l.Y) * s.Z) / 2,
						(math.abs(r.Z) * s.X + math.abs(u.Z) * s.Y + math.abs(l.Z) * s.Z) / 2)
					lo, hi = lo:Min(cf.Position - half), hi:Max(cf.Position + half)
				end
			end
			return lo, hi
		end
		local lo, hi = worldBox()
		if hi.X < lo.X then m:Destroy() return end   -- no parts
		if hi.Z - lo.Z > (hi.X - lo.X) * 1.1 then   -- the long axis along X: a turn from where it is
			m:PivotTo(CFrame.Angles(0, math.rad(90), 0) * m:GetPivot())
			lo, hi = worldBox()
		end
		m:PivotTo(CFrame.new(-(lo + hi) / 2) * m:GetPivot())
		local sz = hi - lo
		m.Parent = world
		model = m
		halfLen = math.max(sz.X, sz.Z) / 2
		-- the height (not the length) fills the view: the view is wide and short
		fitDist = math.max(sz.Y, sz.Z * 0.6, 0.4) / (2 * math.tan(math.rad(cam.FieldOfView) / 2)) * 1.7
	end
	local token = 0
	function pv.Show(weapon, skin)
		local key = tostring(weapon) .. "|" .. tostring(skin)
		if key == pv.key then return end
		pv.key = key
		token += 1
		local mine = token
		caption.Text = weapon and (tostring(weapon) .. (skin and ("  -  " .. tostring(skin)) or "  -  default")) or ""
		if not weapon then setModel(nil) empty.Text = "" return end
		task.spawn(function()
			local ok, m = pcall(builder, weapon, skin)
			if mine ~= token or not Library.Alive then
				if ok and typeof(m) == "Instance" then pcall(function() m:Destroy() end) end
				return
			end
			if ok and typeof(m) == "Instance" then
				setModel(m)
				empty.Text = ""
			else
				setModel(nil)
				empty.Text = "No preview for this item."
			end
		end)
	end

	-- the camera: orbit around the model, auto rotate, zoom
	Library:Connect(RunService.RenderStepped, function(dt)
		if not model then return end
		local g = vpf
		local holder = Library.Holder.Instance
		while g and g ~= holder do
			if g:IsA("GuiObject") and not g.Visible then return end   -- another tab / the menu closed
			g = g.Parent
		end
		if pv.Spin and not pv.Dragging then pv.Yaw += dt * 0.7 end
		local d = math.max(fitDist / pv.Zoom, halfLen * 0.9)
		local dir = Vector3.new(math.sin(pv.Yaw) * math.cos(pv.Pitch), math.sin(pv.Pitch), math.cos(pv.Yaw) * math.cos(pv.Pitch))
		cam.CFrame = CFrame.lookAt(dir * d, Vector3.zero)
	end)
	local hit = Instance.new("TextButton")
	hit.Name = "\0"
	hit.Text, hit.AutoButtonColor, hit.BackgroundTransparency = "", false, 1
	hit.Size, hit.ZIndex = UDim2.fromScale(1, 1), 20
	hit.Parent = frame
	local MB1, TOUCH = Enum.UserInputType.MouseButton1, Enum.UserInputType.Touch
	local lastPos
	Library:Connect(hit.InputBegan, function(i)
		if i.UserInputType == MB1 or i.UserInputType == TOUCH then pv.Dragging, lastPos = true, i.Position end
	end)
	Library:Connect(UserInputService.InputChanged, function(i)
		if pv.Dragging and lastPos and (i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == TOUCH) then
			local d = i.Position - lastPos
			lastPos = i.Position
			pv.Yaw -= d.X * 0.012
			pv.Pitch = math.clamp(pv.Pitch + d.Y * 0.01, -1.2, 1.2)
		end
	end)
	Library:Connect(UserInputService.InputEnded, function(i)
		if i.UserInputType == MB1 or i.UserInputType == TOUCH then pv.Dragging = false end
	end)

	-- the bottom row: zoom slider (left), auto rotate toggle (right)
	local row = fixedFrame(content, UDim2.new(0, 0, 1, -22), UDim2.new(1, 0, 0, 20))
	local zoomRow = fixedFrame(row, UDim2.new(), UDim2.new(1, -150, 1, 0))
	local function small(txt, x, align, width)
		local t = label(zoomRow, txt, UDim2.fromScale(x, 0), UDim2.new(0, width, 1, 0), Library.Theme["Dim Text"], 12, align)
		t.AnchorPoint = Vector2.new(x, 0)
		Library.themed(t, "TextColor3", "Dim Text")
		return t
	end
	small("zoom", 0, Enum.TextXAlignment.Left, 36)
	local value = small("1x", 1, Enum.TextXAlignment.Right, 40)
	local track = Instance.new("Frame")
	track.Name = "\0"
	track.BorderSizePixel = 0
	track.BackgroundColor3 = Library.Theme.Inline
	Library.themed(track, "BackgroundColor3", "Inline")
	track.Position, track.Size = UDim2.new(0, 42, 0.5, -4), UDim2.new(1, -88, 0, 8)
	track.Parent = zoomRow
	local trackStroke = Instance.new("UIStroke", track)
	trackStroke.Color = Library.Theme.Outline
	Library.themed(trackStroke, "Color", "Outline")
	local fill = Instance.new("Frame")
	fill.Name = "\0"
	fill.BorderSizePixel = 0
	fill.BackgroundColor3 = Library.Theme.Accent
	Library.themed(fill, "BackgroundColor3", "Accent")
	fill.Parent = track
	local zflag = tostring(field(Data, "ZoomFlag", "zoomflag") or "SkinPreviewZoom")
	local function setZoom(v)
		v = tonumber(v)
		if not v then return end
		v = math.clamp(Library:Round(v, 0.05), MIN, MAX)
		pv.Zoom = v
		Library.Flags[zflag] = v
		fill.Size = UDim2.new((v - MIN) / (MAX - MIN), 0, 1, 0)
		value.Text = string.format("%.2gx", v)
	end
	Library.SetFlags[zflag] = setZoom
	setZoom(1)
	local zhit = Library.click(track)
	zhit.Size, zhit.Position = UDim2.new(1, 0, 1, 8), UDim2.fromOffset(0, -4)
	local zdrag = false
	local function at(x) setZoom(MIN + (MAX - MIN) * math.clamp((x - track.AbsolutePosition.X) / math.max(track.AbsoluteSize.X, 1), 0, 1)) end
	Library:Connect(zhit.InputBegan, function(i) if i.UserInputType == MB1 or i.UserInputType == TOUCH then zdrag = true at(i.Position.X) end end)
	Library:Connect(UserInputService.InputChanged, function(i) if zdrag and (i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == TOUCH) then at(i.Position.X) end end)
	Library:Connect(UserInputService.InputEnded, function(i) if i.UserInputType == MB1 or i.UserInputType == TOUCH then zdrag = false end end)
	Library:Connect(hit.InputChanged, function(i)
		if i.UserInputType == Enum.UserInputType.MouseWheel then setZoom(pv.Zoom + i.Position.Z * 0.1) end
	end)
	-- auto rotate: the design sheet's Toggle
	do
		local T = Build.Toggle(row)
		T.Root.AnchorPoint, T.Root.Position, T.Root.Size = Vector2.new(1, 0), UDim2.new(1, 0, 0, 0), UDim2.new(0, 140, 0, 19)
		T.label.Text = "auto rotate"
		T.label.Size = UDim2.new(1, -18, 0, 15)
		T.check.AnchorPoint, T.check.Position, T.check.Size = Vector2.new(0.5, 0.5), UDim2.fromScale(0.5, 0.5), UDim2.fromScale(1, 1)
		local sflag = tostring(field(Data, "SpinFlag", "spinflag") or "SkinPreviewSpin")
		local function set(v)
			v = v and true or false
			pv.Spin = v
			Library.Flags[sflag] = v
			Library:ChangeItemTheme(T.box, { BackgroundColor3 = v and "Accent" or "Inline" })
			fx.tween(T.box, { BackgroundColor3 = v and Library.Theme.Accent or Library.Theme.Inline }, 0.14)
			fx.tween(T.check, { BackgroundTransparency = v and 0 or 1 }, 0.14)
		end
		Library.SetFlags[sflag] = set
		Library.click(T.Root, function() set(not pv.Spin) end)
		set(true)
	end
	return pv
end

function Library:SkinChanger(Data)
	local page = self
	if page.Columns ~= 1 then
		Library:Notification("SkinChanger can only be added to a page with 1 column.", 5, Color3.fromRGB(235, 90, 90))
		return nil
	end
	Data = Data or {}
	local flag = field(Data, "Flag", "flag") or Library:NextFlag()
	local callback = field(Data, "Callback", "callback") or function() end
	local height = field(Data, "Height", "height") or 640
	local S = pageBox(page, "Skin Changer", height)
	local pv = skinPreview(page, Data)   -- the 3D preview box under it (when the script gives a builder)
	local content = S.content
	local ch = { Window = page.Window, Page = page, Flag = flag, Callback = callback, Catalog = field(Data, "Catalog", "catalog") or {}, Height = height,
		Selected = {}, Category = 1, Weapon = nil, Query = "", Items = { SkinChanger = Library.Wrap(S.Root) } }

	local function save()
		local ok, json = pcall(function() return HttpService:JSONEncode(ch.Selected) end)
		Library.Flags[flag] = (ok and next(ch.Selected) ~= nil) and json or "{}"   -- an empty selection is "{}" (not "[]")
	end
	save()
	local function fire(w, skin)
		task.spawn(function()
			local ok, err = pcall(callback, w, skin)
			if not ok then warn("[SkinChanger] callback: " .. tostring(err)) end
		end)
	end

	-- layout: categories / weapon chips + search / cards / info / buttons
	local catRow = fixedFrame(content, UDim2.new(), UDim2.new(1, 0, 0, 28))
	Library.listLayout(catRow, 6, Enum.FillDirection.Horizontal)
	local chipRow = Instance.new("ScrollingFrame")
	chipRow.Name = "\0"
	chipRow.BackgroundTransparency, chipRow.BorderSizePixel = 1, 0
	chipRow.ScrollBarThickness = 0
	chipRow.CanvasSize, chipRow.AutomaticCanvasSize, chipRow.ScrollingDirection = UDim2.new(), Enum.AutomaticSize.X, Enum.ScrollingDirection.X
	chipRow.Position, chipRow.Size = UDim2.new(0, 0, 0, 36), UDim2.new(1, -188, 0, 28)
	chipRow.Parent = content
	Library.listLayout(chipRow, 6, Enum.FillDirection.Horizontal)
	local searchHost = Build.Textbox(content)
	searchHost.Root.Position, searchHost.Root.Size = UDim2.new(1, -180, 0, 36), UDim2.new(0, 180, 0, 28)
	searchHost.label.Visible = false
	searchHost.field.Position, searchHost.field.Size = UDim2.new(), UDim2.new(1, 0, 1, 0)
	searchHost.input.Visible = false
	local sbox = Instance.new("TextBox")
	sbox.BackgroundTransparency, sbox.BorderSizePixel = 1, 0
	sbox.Size, sbox.Position = UDim2.new(1, -20, 1, 0), UDim2.new(0, 10, 0, 0)
	sbox.FontFace, sbox.TextSize, sbox.TextXAlignment = Library.Font, 14, Enum.TextXAlignment.Left
	sbox.TextColor3, sbox.PlaceholderColor3 = Library.Theme.Text, Library.Theme["Dim Text"]
	sbox.PlaceholderText, sbox.Text, sbox.ClearTextOnFocus = "Search skins...", "", false
	sbox.Parent = searchHost.field
	local grid = Instance.new("ScrollingFrame")
	grid.Name = "\0"
	grid.BackgroundTransparency, grid.BorderSizePixel = 1, 0
	grid.ScrollBarThickness, grid.ScrollBarImageColor3 = 3, Library.Theme.Inline
	grid.CanvasSize, grid.AutomaticCanvasSize = UDim2.new(), Enum.AutomaticSize.Y
	grid.Position, grid.Size = UDim2.new(0, 0, 0, 72), UDim2.new(1, 0, 1, -72 - 62)
	grid.Parent = content
	local gl = Instance.new("UIGridLayout")
	local GAP, MIN_CARD = 8, 150
	gl.CellSize, gl.CellPadding, gl.SortOrder = UDim2.new(0, 150, 0, 188), UDim2.new(0, GAP, 0, GAP), Enum.SortOrder.LayoutOrder
	gl.Parent = grid
	local emptyLabel = label(content, "", UDim2.new(0, 0, 0, 110), UDim2.new(1, 0, 0, 20), Library.Theme["Dim Text"], 14, Enum.TextXAlignment.Center)
	local info = label(content, "", UDim2.new(0, 0, 1, -54), UDim2.new(1, 0, 0, 18), Library.Theme["Dim Text"], 12)
	local btnRow = fixedFrame(content, UDim2.new(0, 0, 1, -30), UDim2.new(1, 0, 0, 30))
	local resetWeapon = Build.Button(btnRow)
	resetWeapon.Root.Size, resetWeapon.Root.Position = UDim2.new(0.5, -4, 0, 30), UDim2.new()
	resetWeapon.label.Text = "Reset Weapon"
	local resetAll = Build.Button(btnRow)
	resetAll.Root.Size, resetAll.Root.Position = UDim2.new(0.5, -4, 0, 30), UDim2.new(0.5, 4, 0, 0)
	resetAll.label.Text = "Reset All"

	local chipRefs, catRefs = {}, {}
	-- a chip: 28 px high, the label centred in it, the underline on its bottom edge (the template is 22 px high)
	local function styleChip(C, width, text)
		C.Root.Size = UDim2.new(0, width, 0, 28)
		C.text.Text = text
		C.text.Position, C.text.Size = UDim2.new(0, 0, 0, 0), UDim2.new(1, 0, 1, 0)
		C.text.TextSize = 13
		-- the small accent dash under a weapon that has a skin chosen
		C.dot.AnchorPoint, C.dot.Position, C.dot.Size = Vector2.new(0.5, 1), UDim2.new(0.5, 0, 1, -3), UDim2.new(0, 10, 0, 2)
	end
	-- every chip of a row is as wide as the longest label (min 64), so the row reads as columns
	local function chipWidth(names)
		local longest = 0
		for _, n in names do longest = math.max(longest, #tostring(n)) end
		return math.max(64, longest * 7 + 28)
	end
	local function weaponsOf(cat) return cat and cat.Weapons or {} end
	local function currentCat() return ch.Catalog[ch.Category] end
	local function currentWeapon()
		for _, w in weaponsOf(currentCat()) do if w.Name == ch.Weapon then return w end end
	end
	local function count() local n = 0 for _ in ch.Selected do n += 1 end return n end
	local function refreshInfo()
		local n = count()
		local sel = ch.Weapon and ch.Selected[ch.Weapon]
		info.Text = (ch.Weapon and (ch.Weapon .. ":  " .. (sel or "default") .. "     |     ") or "") .. n .. (n == 1 and " skin" or " skins") .. " chosen"
	end
	local function paintChip(ref, active)
		Library.themed(ref.Root, "BackgroundColor3", active and "Accent" or "Element")
		Library.themed(ref.text, "TextColor3", active and "Bright Text" or "Dim Text")
		ref.dot.BackgroundColor3 = active and Color3.new(1, 1, 1) or Library.Theme.Accent
	end
	local renderCards, setCategory

	local function paintStates()
		for name, ref in chipRefs do ref.dot.Visible = ch.Selected[name] ~= nil end
	end

	local function buildChips()
		for _, r in chipRefs do pcall(function() r.Root:Destroy() end) end
		table.clear(chipRefs)
		local names = {}
		for _, w in weaponsOf(currentCat()) do names[#names + 1] = w.Name end
		local width = chipWidth(names)
		for i, w in weaponsOf(currentCat()) do
			local C = Build.Chip(chipRow)
			C.Root.LayoutOrder = i
			styleChip(C, width, w.Name)
			C.dot.ZIndex = C.Root.ZIndex + 3
			chipRefs[w.Name] = C
			paintChip(C, w.Name == ch.Weapon)
			Library.click(C.Root, function()
				ch.Weapon = w.Name
				for name, ref in chipRefs do paintChip(ref, name == ch.Weapon) end
				renderCards()
			end)
		end
		paintStates()
	end

	local function categoryOf(weapon)
		for _, cat in ch.Catalog do for _, w in cat.Weapons or {} do if w.Name == weapon then return cat end end end
	end

	function ch:Select(weapon, skin)
		if type(weapon) ~= "string" then return end
		local cat = categoryOf(weapon)
		if skin ~= nil and cat and cat.Exclusive then
			for other in ch.Selected do
				if other ~= weapon then
					for _, w in cat.Weapons do if w.Name == other then ch.Selected[other] = nil fire(other, nil) break end end
				end
			end
		end
		ch.Selected[weapon] = skin
		save()
		paintStates()
		renderCards()
		fire(weapon, skin)
	end
	function ch:Toggle(weapon, skin)
		if ch.Selected[weapon] == skin then skin = nil end
		ch:Select(weapon, skin)
	end
	function ch:Get() return table.clone(ch.Selected) end
	function ch:ResetAll()
		local old = ch.Selected
		ch.Selected = {}
		save()
		paintStates()
		renderCards()
		for w in old do fire(w, nil) end
	end

	local function cardClick(weapon, skin) ch:Toggle(weapon, skin) end
	-- the parts of a card follow the card's size (cw x chh): the image takes the upper ~58 %, the name and the collection sit under it
	local cards = {}
	local function layoutCard(C, cw, chh)
		local imgH = math.floor(chh * 0.6)
		C.image.Position, C.image.Size = UDim2.new(0, 10, 0, 10), UDim2.new(1, -20, 0, imgH)
		C.glow.AnchorPoint, C.glow.Position = Vector2.new(0.5, 0.5), UDim2.new(0.5, 0, 0, 10 + imgH * 0.55)
		C.glow.Size = UDim2.fromOffset(math.floor(cw * 1.15), math.floor(cw * 1.15))
		C.name.Position, C.name.Size = UDim2.new(0, 12, 0, 10 + imgH + 8), UDim2.new(1, -24, 0, 18)
		C.name.TextSize, C.name.TextXAlignment = 14, Enum.TextXAlignment.Left
		C.sub.Position, C.sub.Size = UDim2.new(0, 12, 0, 10 + imgH + 28), UDim2.new(1, -24, 0, 16)
		C.sub.TextSize, C.sub.TextXAlignment = 12, Enum.TextXAlignment.Left
		C.sub.TextTruncate = Enum.TextTruncate.AtEnd
		C.stripe.AnchorPoint, C.stripe.Position, C.stripe.Size = Vector2.new(0, 1), UDim2.new(0, 12, 1, -9), UDim2.new(1, -24, 0, 3)
		C.badge.AnchorPoint, C.badge.Position, C.badge.Size = Vector2.new(1, 0), UDim2.new(1, -8, 0, 8), UDim2.fromOffset(20, 20)
	end
	-- the rarity light: a soft round glow behind the weapon and a faint wash rising from the bottom edge, both in the rarity colour
	local function lightCard(C, col)
		local g = Instance.new("ImageLabel")
		g.Name = "\0"
		g.BackgroundTransparency, g.BorderSizePixel = 1, 0
		g.Image = Build.IconAsset.fx_ripple or ""
		g.ImageColor3, g.ImageTransparency = col, 0.72
		g.Size = UDim2.fromScale(1, 1)
		g.ZIndex = C.glow.ZIndex
		g.Parent = C.glow
		C.glow.BackgroundTransparency = 1
		local wash = Instance.new("Frame")
		wash.Name = "\0"
		wash.BorderSizePixel = 0
		wash.BackgroundColor3 = col
		wash.AnchorPoint, wash.Position, wash.Size = Vector2.new(0, 1), UDim2.fromScale(0, 1), UDim2.fromScale(1, 0.55)
		wash.ZIndex = C.Root.ZIndex
		local wg = Instance.new("UIGradient", wash)
		wg.Rotation = 90
		wg.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(1, 0.86) })
		Instance.new("UICorner", wash).CornerRadius = UDim.new(0, 8)
		wash.Parent = C.Root
		C.image.ZIndex = C.glow.ZIndex + 1
		for _, part in { C.name, C.sub, C.stripe, C.badge } do part.ZIndex = C.Root.ZIndex + 3 end
		for _, d in C.badge:GetDescendants() do if d:IsA("GuiObject") then d.ZIndex = C.Root.ZIndex + 4 end end
		C.Root.ClipsDescendants = true
		return g
	end
	-- cards fill the row edge to edge: as many columns as fit MIN_CARD, the rest of the width shared out (sizes are offsets, so the
	-- window's UIScale is divided out; the card box's own height gives the scale)
	local cardW, cardH = MIN_CARD, math.floor(MIN_CARD * 1.25)
	local function relayout()
		local k = S.card.AbsoluteSize.Y / math.max(height, 1)
		if k <= 0 then k = 1 end
		local W = grid.AbsoluteSize.X / k - 6
		if W < MIN_CARD then return end
		local cols = math.max(1, math.floor((W + GAP) / (MIN_CARD + GAP)))
		local cw = math.floor((W - GAP * (cols - 1)) / cols)
		local chh = math.floor(cw * 1.25)
		if cw == cardW and chh == cardH then return end
		cardW, cardH = cw, chh
		gl.CellSize = UDim2.fromOffset(cw, chh)
		for c in cards do
			if c.Root.Parent then layoutCard(c, cw, chh) else cards[c] = nil end
		end
	end
	Library:Connect(grid:GetPropertyChangedSignal("AbsoluteSize"), relayout)
	local function makeCard(order, weapon, entry)
		local C = Build.SkinCard(grid)
		C.Root.LayoutOrder = order
		layoutCard(C, cardW, cardH)
		cards[C] = true
		local on
		local light
		if entry then
			on = ch.Selected[weapon] == entry.Skin
			local col = entry.Color or Library.Theme["Dim Text"]
			C.stripe.BackgroundColor3 = col
			C.sub.TextColor3 = col
			light = lightCard(C, col)
			local img = Instance.new("ImageLabel")
			img.BackgroundTransparency, img.Size, img.ScaleType = 1, UDim2.fromScale(1, 1), Enum.ScaleType.Fit
			img.Image = tostring(entry.Image or "")
			img.Parent = C.image
			C.name.Text = tostring(entry.Skin)
			C.sub.Text = tostring(entry.Sub or entry.Rarity or "")
		else
			on = ch.Selected[weapon] == nil
			C.stripe.BackgroundColor3 = Library.Theme.Border
			light = lightCard(C, Library.Theme["Dim Text"])
			label(C.image, "DEFAULT", UDim2.new(), UDim2.fromScale(1, 1), Library.Theme["Dim Text"], 13, Enum.TextXAlignment.Center)
			C.name.Text = "Default " .. weapon
			C.sub.Text = ""
		end
		C.name.TextTruncate = Enum.TextTruncate.AtEnd
		C.badge.Visible = on and true or false
		local stroke = C.Root:FindFirstChildOfClass("UIStroke")
		if stroke then stroke.Color = on and Library.Theme.Accent or Library.Theme.Border stroke.Thickness = on and 2 or 1 end
		local cardBtn = Library.click(C.Root, function() cardClick(weapon, entry and entry.Skin or nil) end)
		cardBtn.ZIndex = C.Root.ZIndex + 10
		-- hover: the light grows brighter and the edge lifts
		Library.fx.hover(cardBtn, function()
			Library.fx.tween(light, { ImageTransparency = 0.5 }, 0.15)
			if stroke and not on then Library.fx.tween(stroke, { Color = Library.Theme.Highlight }, 0.15) end
		end, function()
			Library.fx.tween(light, { ImageTransparency = 0.72 }, 0.2)
			if stroke and not on then Library.fx.tween(stroke, { Color = Library.Theme.Border }, 0.2) end
		end)
		if pv then
			-- hovering a card previews it; leaving shows the chosen one again
			Library:Connect(cardBtn.MouseEnter, function() pv.Show(weapon, entry and entry.Skin or nil) end)
			Library:Connect(cardBtn.MouseLeave, function() if ch.PreviewCurrent then ch.PreviewCurrent() end end)
		end
		return C
	end

	function ch.PreviewCurrent()
		if pv then pv.Show(ch.Weapon, ch.Weapon and ch.Selected[ch.Weapon] or nil) end
	end
	function renderCards()
		ch.PreviewCurrent()
		for _, c in grid:GetChildren() do if c:IsA("Frame") then c:Destroy() end end
		table.clear(cards)
		relayout()
		grid.CanvasPosition = Vector2.new()
		emptyLabel.Text = ""
		refreshInfo()
		local w = currentWeapon()
		if not w then emptyLabel.Text = "No weapon in this category." return end
		local skins, q = {}, ch.Query:lower()
		for _, e in w.Skins or {} do
			if q == "" or tostring(e.Skin):lower():find(q, 1, true) or tostring(e.Sub or ""):lower():find(q, 1, true) or tostring(e.Rarity or ""):lower():find(q, 1, true) then
				skins[#skins + 1] = e
			end
		end
		table.sort(skins, function(a, b)
			local ra, rb = RARITY_RANK[a.Rarity] or 9, RARITY_RANK[b.Rarity] or 9
			if ra ~= rb then return ra < rb end
			return tostring(a.Skin) < tostring(b.Skin)
		end)
		local order = 0
		if q == "" then order += 1 makeCard(order, w.Name, nil) end
		for _, e in skins do order += 1 makeCard(order, w.Name, e) end
		if #skins == 0 then emptyLabel.Text = q == "" and "This weapon has no skins." or ('No skin matches "' .. ch.Query .. '".') end
	end

	function setCategory(i)
		ch.Category = i
		for idx, ref in catRefs do paintChip(ref, idx == i) end
		local keep = false
		for _, w in weaponsOf(currentCat()) do if w.Name == ch.Weapon then keep = true end end
		if not keep then local first = weaponsOf(currentCat())[1] ch.Weapon = first and first.Name or nil end
		buildChips()
		renderCards()
	end
	local function buildCategories()
		for _, r in catRefs do pcall(function() r.Root:Destroy() end) end
		table.clear(catRefs)
		local names = {}
		for _, cat in ch.Catalog do names[#names + 1] = cat.Name end
		local width = chipWidth(names)
		for i, cat in ch.Catalog do
			local C = Build.Chip(catRow)
			C.Root.LayoutOrder = i
			styleChip(C, width, cat.Name)
			C.dot.Visible = false
			catRefs[i] = C
			Library.click(C.Root, function() setCategory(i) end)
		end
	end
	function ch:SetCatalog(c)
		ch.Catalog = c or {}
		if ch.Category > #ch.Catalog then ch.Category = 1 end
		buildCategories()
		setCategory(ch.Category)
	end
	function ch:Refresh() setCategory(ch.Category) end

	local token = 0
	Library:Connect(sbox:GetPropertyChangedSignal("Text"), function()
		token += 1
		local mine = token
		task.delay(0.15, function() if mine == token then ch.Query = sbox.Text renderCards() end end)
	end)
	Library.click(resetWeapon.Root, function() if ch.Weapon and ch.Selected[ch.Weapon] ~= nil then ch:Select(ch.Weapon, nil) end end)
	Library.click(resetAll.Root, function() ch:ResetAll() end)

	Library.SetFlags[flag] = function(value)
		local decoded = value
		if type(value) == "string" then
			local ok, d = pcall(function() return HttpService:JSONDecode(value) end)
			decoded = ok and d or nil
		end
		if type(decoded) ~= "table" then return end
		local new = {}
		for w, s in decoded do if type(w) == "string" and type(s) == "string" then new[w] = s end end
		local old = ch.Selected
		ch.Selected = new
		save()
		paintStates()
		renderCards()
		for w, s in new do if old[w] ~= s then fire(w, s) end end
		for w in old do if new[w] == nil then fire(w, nil) end end
	end

	buildCategories()
	setCategory(1)
	return ch
end


-- ===== runtime/extras.lua =====
-- uilibAurora runtime part 8: the extras - ESP preview window, body part picker, loader.

-- ---- Library:EspPreview(Data) -> preview ----
-- A floating window with a turning model of your character (a ViewportFrame) and the ESP drawn over it, laid out like a real ESP: flags right of the box,
-- name + weapon above it, distance below. preview:Sync({ key = value, ... }) sets many at once, preview:Set(key, value) one. Keys (defaults in `state` below):
--   Box, BoxColor, OutlineColor | Fill, FillColor1, FillColor2, FillTransparency1, FillTransparency2, FillSpin | Glow
--   Name, NameText, NameColor, NameSize, NameOutline, NameOutlineColor | Distance | Weapon, WeaponText, FlagSize, FlagColor, FlagLines ({ { text, col } ... })
--   Health, HealthPos (Left / Right / Top / Bottom), HealthGap, HealthWidth, HealthOutline (Full / Fit / None), HealthOutlineColor, HealthGradient, HealthColor1 / 2 / 3,
--   HealthText, HealthTextFollow, HealthTextHideFull, HealthTextGradient, HealthTextSize
--   Chams, ChamsColor, ChamsStyle (Flat / Liquid / Test), ChamsTransparency, LiquidSpeed, TestGlow, ChamsWalls, ChamsOutline, ChamsOutlineColor, ChamsOutlineThickness,
--   ChamsOutlineWalls, ChamsVisCheck, ChamsVisibleColor | Skeleton, HeadCircle, LookDir, LookCone, LookLength, LineColor | Wall, AutoRotate
-- The view is 3D: drag in it to turn the camera around the model, scroll to zoom. Two toggles under it: "half body behind wall" (a waist-high wall
-- in front of the model, flag Data.WallFlag or "EspPreviewWall") and "auto rotate" (flag Data.SpinFlag or "EspPreviewSpin").
-- Or Data.Flags = { Box = "MyBoxFlag", ... } and it follows those flags (Color3 or colorpicker flags). The model only turns while the preview is shown.
-- A zoom slider sits under the view (flag Data.ZoomFlag, default "EspPreviewZoom", saved with configs). Text is drawn like the ESP: flags, weapon, distance and the
-- health number in Arial, one size under the setting, with a black outline; the name in Code. Lines have an outline in OutlineColor.
local PREVIEW_BONES = {
	{ "Head", "UpperTorso" }, { "UpperTorso", "LowerTorso" },
	{ "UpperTorso", "LeftUpperArm" }, { "LeftUpperArm", "LeftLowerArm" }, { "LeftLowerArm", "LeftHand" },
	{ "UpperTorso", "RightUpperArm" }, { "RightUpperArm", "RightLowerArm" }, { "RightLowerArm", "RightHand" },
	{ "LowerTorso", "LeftUpperLeg" }, { "LeftUpperLeg", "LeftLowerLeg" }, { "LeftLowerLeg", "LeftFoot" },
	{ "LowerTorso", "RightUpperLeg" }, { "RightUpperLeg", "RightLowerLeg" }, { "RightLowerLeg", "RightFoot" },
}
function Library:EspPreview(Data)
	Data = Data or {}
	local fx = Library.fx
	local P = Build.EspPreview(Library.Holder.Instance)
	local root = P.Root
	root.Name = "\0"
	root.ZIndex = 1400
	root.Size = UDim2.fromOffset(320, 508)   -- room for the flags right of the box, the target tabs, the two toggles and the zoom
	-- (the generated positions count the card's 1 px border; the runtime parts are placed from the inner edge, so these are set exactly)
	P.view.Position, P.view.Size = UDim2.fromOffset(12, 84), UDim2.new(1, -24, 1, -(84 + 92))
	if P.tabs then P.tabs.Position, P.tabs.Size = UDim2.fromOffset(12, 48), UDim2.new(1, -24, 0, 28) end
	P.title.Text = tostring(Library.field(Data, "Name", "name") or "esp preview")
	P.view.ClipsDescendants = true
	fx.shadow(root, { radius = 12, transparency = 0.35 })
	-- pinned to the first window: its top edge level with the window's, 12 px right of it, following every move / resize (on the left
	-- side instead when there is no room on the right). Without a window it sits right of the screen centre and can be dragged.
	local main = Library.Windows[1]
	if main then
		local r = main._W.Root
		local GAP = 12
		local function pin()
			if not root.Parent then return end
			local a, s = r.AbsolutePosition, r.AbsoluteSize
			local sc = root:FindFirstChildOfClass("UIScale")
			local w = root.AbsoluteSize.X
			local screen = root.Parent.AbsoluteSize.X
			local x = a.X + s.X + GAP
			if x + w > screen - 4 and a.X - GAP - w >= 4 then x = a.X - GAP - w end
			root.AnchorPoint = Vector2.zero
			-- Position is relative to the holder, whose AbsolutePosition starts above the top bar inset
			local o = root.Parent.AbsolutePosition
			root.Position = UDim2.fromOffset(math.floor(x - o.X), math.floor(a.Y - o.Y))
		end
		Library:Connect(r:GetPropertyChangedSignal("AbsolutePosition"), pin)
		Library:Connect(r:GetPropertyChangedSignal("AbsoluteSize"), pin)
		task.defer(pin)
		pin()
	else
		root.Position = UDim2.new(0.5, 330, 0.5, -165)
		Library.MakeDraggable(P.title, root)
	end
	local white, black = Color3.new(1, 1, 1), Color3.new(0, 0, 0)
	local state = {
		Box = true, BoxColor = white, OutlineColor = black,
		Fill = false, FillColor1 = white, FillColor2 = white, FillTransparency1 = 0.5, FillTransparency2 = 1, FillSpin = false, Glow = false,
		Name = true, NameText = Players.LocalPlayer.Name, NameColor = white, NameSize = 13, NameOutline = true, NameOutlineColor = black,
		Distance = true, Weapon = true, WeaponText = tostring(Library.field(Data, "Weapon", "weapon") or "AK-47"), FlagSize = 12, FlagColor = Color3.fromRGB(235, 235, 235), FlagLines = {},
		Health = true, HealthPos = "Left", HealthGap = 2, HealthWidth = 2, HealthOutline = "Full", HealthOutlineColor = black, HealthGradient = false,
		HealthColor1 = Color3.fromRGB(0, 255, 0), HealthColor2 = Color3.fromRGB(255, 255, 0), HealthColor3 = Color3.fromRGB(255, 0, 0),
		HealthText = false, HealthTextFollow = false, HealthTextHideFull = false, HealthTextGradient = false, HealthTextSize = 9,
		Chams = false, ChamsColor = Library.Theme.Accent, ChamsStyle = "Flat", ChamsTransparency = 0, LiquidSpeed = 1, TestGlow = 1,
		ChamsWalls = true, ChamsOutline = false, ChamsOutlineColor = white, ChamsOutlineThickness = 0.12, ChamsOutlineWalls = true,
		ChamsVisCheck = false, ChamsVisibleColor = Color3.fromRGB(60, 255, 60), Wall = false, AutoRotate = true,
		Skeleton = false, HeadCircle = false, LookDir = false, LookCone = true, LookLength = 8, LineColor = white, Zoom = 1,
	}
	local ARIAL, CODE = Font.fromEnum(Enum.Font.Arial), Font.fromEnum(Enum.Font.Code)
	-- editing: parts that are off stay drawn faintly (GHOST) so they can be clicked back on; editHooks is filled in further down
	local EDIT = Library.field(Data, "Editable", "editable") ~= false
	local GHOST = 0.78
	local editHooks = {}

	-- the model: a clone of your character in a ViewportFrame. A second ViewportFrame on top of it, with the same camera, is the "through walls"
	-- layer: what the real ESP draws AlwaysOnTop (the chams boxes, their outline, the Liquid shell) goes there and shows over the wall; the rest
	-- sits in the first one, where the wall hides it. Roblox draws no adornments or Highlights inside a ViewportFrame, so the chams are built from
	-- parts the way the in-game ones are laid out: one box per body part (its size, over the skin), thin boxes along its edges for the outline.
	local function viewport(z)
		local v = Instance.new("ViewportFrame")
		v.Name = "\0"
		v.BackgroundTransparency, v.BorderSizePixel = 1, 0
		v.Size = UDim2.fromScale(1, 1)
		v.Ambient, v.LightColor = Color3.fromRGB(150, 150, 150), white
		v.LightDirection = Vector3.new(-0.4, -1, -0.6)
		v.ZIndex = z
		v.Parent = P.view
		local c = Instance.new("Camera")
		c.FieldOfView = 40
		c.Parent = v
		v.CurrentCamera = c
		local w = Instance.new("WorldModel")
		w.Parent = v
		return v, c, w
	end
	local vp, cam, world = viewport(1)
	local vpTop, camTop, worldTop = viewport(2)
	local CHAM_PARTS = {
		"Head", "UpperTorso", "LowerTorso", "LeftUpperArm", "LeftLowerArm", "LeftHand", "RightUpperArm", "RightLowerArm", "RightHand",
		"LeftUpperLeg", "LeftLowerLeg", "LeftFoot", "RightUpperLeg", "RightLowerLeg", "RightFoot",
	}
	local FULL_EDGES = { Head = true, UpperTorso = true, LowerTorso = true }
	local chamsBase, chamsTop = Instance.new("Folder"), Instance.new("Folder")
	chamsBase.Parent, chamsTop.Parent = world, worldTop
	local model, parts, body, wall = nil, {}, {}, nil
	local chamSig, chamFills, chamLines, shells = nil, {}, {}, {}
	local glows, neonParts = {}, {}   -- the Test style: glow hint shells, the body parts turned Neon
	local shellOf = setmetatable({}, { __mode = "k" })   -- shell / glow copy -> the body part it covers
	local testSaved = { sas = {}, tex = {}, decals = {} }   -- what the Test style set aside on the clone (put back by restoreBody)
	local function buildModel()
		if model then model:Destroy() model, parts, body = nil, {}, {} end
		if wall then wall:Destroy() wall = nil end
		chamSig = nil
		local char = Players.LocalPlayer.Character
		if not char then return end
		local was = char.Archivable
		char.Archivable = true
		local ok, c = pcall(function() return char:Clone() end)
		char.Archivable = was
		if not (ok and c) then return end
		for _, d in c:GetDescendants() do
			if d:IsA("Script") or d:IsA("LocalScript") or d:IsA("ModuleScript") or d:IsA("Sound") then d:Destroy()
			elseif d:IsA("BasePart") then
				d.Anchored = true
				parts[#parts + 1] = { part = d, color = d.Color, mat = d.Material, trans = d.Transparency, refl = d.Reflectance }
			end
		end
		c:PivotTo(CFrame.new())
		c.Parent = world
		model = c
		for _, n in CHAM_PARTS do
			local p = c:FindFirstChild(n)
			if p and p:IsA("BasePart") then body[#body + 1] = p end
		end
		-- the half wall: across the front of the model (it faces -Z), from under the feet up to the waist
		local lo, hi = math.huge, -math.huge
		for _, p in body do
			lo, hi = math.min(lo, p.Position.Y - p.Size.Y / 2), math.max(hi, p.Position.Y + p.Size.Y / 2)
		end
		if lo < hi then
			local top = lo + (hi - lo) * 0.5
			wall = Instance.new("Part")
			wall.Name = "PreviewWall"
			wall.Anchored, wall.CanCollide, wall.CastShadow = true, false, false
			wall.Material, wall.Color = Enum.Material.Concrete, Color3.fromRGB(120, 116, 110)
			wall.TopSurface, wall.BottomSurface = Enum.SurfaceType.Smooth, Enum.SurfaceType.Smooth
			wall.Size = Vector3.new(6, top - lo + 0.5, 0.6)
			wall.CFrame = CFrame.new(0, (top + lo - 0.5) / 2, -2.4)
		end
	end
	local function clearChams()
		chamsBase:ClearAllChildren()
		chamsTop:ClearAllChildren()
		chamFills, chamLines, shells, glows, neonParts = {}, {}, {}, {}, {}
	end
	local function boxPart(size, cf, parent)
		local b = Instance.new("Part")
		b.Name = "Cham"
		b.Anchored, b.CanCollide, b.CanQuery, b.CastShadow = true, false, false, false
		b.Material = Enum.Material.SmoothPlastic
		b.TopSurface, b.BottomSurface = Enum.SurfaceType.Smooth, Enum.SurfaceType.Smooth
		b.Size, b.CFrame = size, cf
		b.Parent = parent
		return b
	end
	-- the outline of one part: thin boxes on its edges (all 12 for head / torso, the 4 long ones for limbs), like the in-game chams
	local function edges(p, thick, full, parent)
		local h = p.Size / 2
		local function corner(i)
			return Vector3.new(i % 2 == 0 and -h.X or h.X, math.floor(i / 2) % 2 == 0 and -h.Y or h.Y, math.floor(i / 4) % 2 == 0 and -h.Z or h.Z)
		end
		local axes = { 1, 2, 4 }
		if not full then
			local sz = p.Size
			axes = { sz.X >= sz.Y and (sz.X >= sz.Z and 1 or 4) or (sz.Y >= sz.Z and 2 or 4) }
		end
		for i = 0, 7 do
			for _, bit in axes do
				if math.floor(i / bit) % 2 == 0 then
					local a, b = corner(i), corner(i + bit)
					local d = b - a
					chamLines[#chamLines + 1] = boxPart(Vector3.new(math.abs(d.X) + thick, math.abs(d.Y) + thick, math.abs(d.Z) + thick), p.CFrame * CFrame.new((a + b) / 2), parent)
				end
			end
		end
	end
	local function restoreBody()
		for _, p in parts do
			p.part.Material, p.part.Color, p.part.Transparency, p.part.Reflectance = p.mat, p.color, p.trans, p.refl
		end
		for _, e in testSaved.sas do pcall(function() e[1].Parent = e[2] end) end
		for mp, tex in testSaved.tex do pcall(function() mp.TextureID = tex end) end
		for d, tr in testSaved.decals do pcall(function() d.Transparency = tr end) end
		testSaved = { sas = {}, tex = {}, decals = {} }
	end
	-- (re)built when a setting that changes their shape moves; their colours are set every frame (chamsFrame)
	local function paintChams()
		-- the wall is destroyed with the preview (unload / the window going away) while a script's Sync can still run: its Parent is locked then
		if wall and not pcall(function() wall.Parent = state.Wall and world or nil end) then wall = nil end
		local sig = table.concat({ tostring(state.Chams), tostring(state.ChamsStyle), tostring(state.ChamsWalls), tostring(state.ChamsOutline),
			tostring(state.ChamsOutlineThickness), tostring(state.ChamsOutlineWalls), tostring(state.ChamsTransparency), tostring(model),
			tostring(state.ChamsStyle == "Test" and state.Wall), tostring((tonumber(state.TestGlow) or 0) > 0) }, "|")
		if sig == chamSig then return end
		chamSig = sig
		clearChams()
		restoreBody()
		if not (state.Chams and model) then return end
		local fillTo = state.ChamsWalls and chamsTop or chamsBase
		-- a tinted copy of every body part, a little bigger (the shell the in-game Highlight stands for)
		local function makeShells(list, parent, scale, material)
			for _, p in body do
				local okS, sh = pcall(function() return p:Clone() end)
				if okS and sh then
					sh:ClearAllChildren()
					if sh:IsA("MeshPart") then pcall(function() sh.TextureID = "" end) end
					sh.Name = "ChamShell"
					sh.Material, sh.CastShadow = material or Enum.Material.SmoothPlastic, false
					sh.Size, sh.CFrame = p.Size * scale, p.CFrame
					sh.Parent = parent
					shellOf[sh] = p
					list[#list + 1] = sh
				end
			end
		end
		if state.ChamsStyle == "Liquid" then
			-- the body turns to tinted glass (the wave runs up it) and a shell around it stands for the Highlight
			local transp = math.clamp((tonumber(state.ChamsTransparency) or 0) * 0.7, 0, 0.9)
			for _, p in body do p.Material, p.Transparency = Enum.Material.Glass, transp end
			makeShells(shells, fillTo, 1.05)
			return
		end
		if state.ChamsStyle == "Test" then
			-- like the in-game Test chams: every visible part of the body is Neon (what hides the material, the SurfaceAppearance, the mesh
			-- texture and decals, is set aside until the next rebuild; weapons are left alone). Every frame (chamsFrame): while any body part is
			-- behind something (a ray from the camera) the smooth liquid shell covers the body (like the in-game Highlight); the Neon parts carry
			-- a bigger Neon copy that hints at the bloom (a viewport has none)
			for _, p in parts do
				local part = p.part
				if part.Transparency < 0.95 and part.Name ~= "HumanoidRootPart" and not part:FindFirstAncestor("WeaponModel") and not part:FindFirstAncestor("WeaponAttachments") then
					for _, k in part:GetChildren() do
						if k:IsA("SurfaceAppearance") then
							testSaved.sas[#testSaved.sas + 1] = { k, part }
							k.Parent = nil
						elseif (k:IsA("Decal") or k:IsA("Texture")) and k.Transparency < 1 then
							testSaved.decals[k] = k.Transparency
							k.Transparency = 1
						end
					end
					if part:IsA("MeshPart") and part.TextureID ~= "" then
						testSaved.tex[part] = part.TextureID
						part.TextureID = ""
					end
					part.Material = Enum.Material.Neon
					neonParts[#neonParts + 1] = part
				end
			end
			if (tonumber(state.TestGlow) or 0) > 0 then makeShells(glows, chamsBase, 1.1, Enum.Material.Neon) end
			if state.ChamsWalls then makeShells(shells, chamsTop, 1.05) end
			return
		end
		for _, p in body do chamFills[#chamFills + 1] = boxPart(p.Size, p.CFrame, fillTo) end
		if state.ChamsOutline then
			local thick = math.clamp(tonumber(state.ChamsOutlineThickness) or 0.12, 0.02, 1)
			local lineTo = state.ChamsOutlineWalls and chamsTop or chamsBase
			for _, p in body do edges(p, thick, FULL_EDGES[p.Name] == true, lineTo) end
		end
	end

	-- the overlay (the box is a fixed frame around where the turning model stands)
	local overlay = Instance.new("Frame")
	overlay.Name = "\0"
	overlay.BackgroundTransparency = 1
	overlay.Size = UDim2.fromScale(1, 1)
	overlay.ZIndex = 5
	overlay.Parent = P.view
	local box = Instance.new("Frame")
	box.Name = "\0"
	box.BackgroundTransparency = 1
	box.Position, box.Size = UDim2.fromScale(0.35, 0.15), UDim2.fromOffset(100, 200)   -- (fitted to the model every frame)
	box.Parent = overlay
	local fill = Instance.new("Frame")
	fill.Name = "\0"
	fill.BorderSizePixel = 0
	fill.BackgroundColor3 = white
	fill.Size = UDim2.fromScale(1, 1)
	fill.Parent = box
	local fillGrad = Instance.new("UIGradient", fill)
	local glow = fx.shadow(box, { force = true, glow = true, radius = 10, transparency = 0.45, color = white })
	local boxStroke = Instance.new("UIStroke", box)
	boxStroke.Thickness = 1
	local boxOuter = Instance.new("Frame")
	boxOuter.Name = "\0"
	boxOuter.BackgroundTransparency = 1
	boxOuter.AnchorPoint, boxOuter.Position, boxOuter.Size = Vector2.new(0.5, 0.5), UDim2.fromScale(0.5, 0.5), UDim2.new(1, 2, 1, 2)
	boxOuter.Parent = box
	local outer = Instance.new("UIStroke", boxOuter)
	outer.Thickness = 1
	local function text(size)
		local t = Instance.new("TextLabel")
		t.Name = "\0"
		t.BackgroundTransparency = 1
		t.FontFace, t.TextSize = ARIAL, size or 12
		t.TextColor3 = white
		t.TextStrokeTransparency, t.TextStrokeColor3 = 0, black
		t.Size = UDim2.fromOffset(160, size or 12)
		t.ZIndex = 3
		t.Parent = box
		return t
	end
	local nameT, weapT, distT, hpT = text(13), text(12), text(12), text(9)
	nameT.FontFace = CODE
	nameT.AnchorPoint, weapT.AnchorPoint, distT.AnchorPoint = Vector2.new(0.5, 1), Vector2.new(0.5, 1), Vector2.new(0.5, 0)
	local hpBack = Instance.new("Frame")
	hpBack.Name = "\0"
	hpBack.BorderSizePixel = 0
	hpBack.Parent = box
	local hpFill = Instance.new("Frame")
	hpFill.Name = "\0"
	hpFill.BorderSizePixel = 0
	hpFill.Parent = hpBack
	local flagRows = {}

	-- skeleton, head circle, look line: projected from the model each frame
	local lines = Instance.new("Frame")
	lines.Name = "\0"
	lines.BackgroundTransparency = 1
	lines.Size = UDim2.fromScale(1, 1)
	lines.ZIndex = 4
	lines.Parent = overlay
	local function line(z)
		local l = Instance.new("Frame")
		l.Name = "\0"
		l.BorderSizePixel = 0
		l.AnchorPoint = Vector2.new(0.5, 0.5)
		l.Visible = false
		l.ZIndex = z or 2
		l.Parent = lines
		return l
	end
	local bones, boneEdges = {}, {}
	for i = 1, #PREVIEW_BONES do bones[i], boneEdges[i] = line(), line(1) end
	local lookLine, lookEdge, lookTip = line(), line(1), line()
	lookTip.Rotation = 45
	local function ring(z, thick)
		local f = line(z)
		f.BackgroundTransparency = 1
		Instance.new("UICorner", f).CornerRadius = UDim.new(1, 0)
		local st = Instance.new("UIStroke", f)
		st.Thickness = thick
		return f, st
	end
	local headRing, ringStroke = ring(2, 1)
	local headEdge, edgeStroke = ring(1, 3)
	local function project(pos)
		local o = cam.CFrame:PointToObjectSpace(pos)
		if o.Z >= -0.1 then return nil end
		local size = P.view.AbsoluteSize
		local t = math.tan(math.rad(cam.FieldOfView / 2))
		return Vector2.new((0.5 + o.X / (-o.Z * t * (size.X / math.max(size.Y, 1))) / 2) * size.X, (0.5 - o.Y / (-o.Z * t) / 2) * size.Y), o.Z
	end
	local function place(l, a, b, thick)
		local d, m = b - a, (a + b) / 2
		l.Position, l.Size, l.Rotation = UDim2.fromOffset(m.X, m.Y), UDim2.fromOffset(d.Magnitude + (thick or 1), thick or 1), math.deg(math.atan2(d.Y, d.X))
		l.Visible = true
	end
	local function hpColor(hp)
		if hp > 0.5 then return state.HealthColor2:Lerp(state.HealthColor1, (hp - 0.5) * 2) end
		return state.HealthColor3:Lerp(state.HealthColor2, hp * 2)
	end

	local function paint()
		boxStroke.Enabled, outer.Enabled = state.Box or EDIT, state.Box or EDIT
		boxStroke.Transparency, outer.Transparency = state.Box and 0 or GHOST, state.Box and 0 or 1
		boxStroke.Color, outer.Color = state.BoxColor, state.OutlineColor
		fill.Visible = state.Box and state.Fill
		fillGrad.Color = ColorSequence.new(state.FillColor1, state.FillColor2)
		fillGrad.Transparency = NumberSequence.new(math.clamp(state.FillTransparency1, 0, 1), math.clamp(state.FillTransparency2, 0, 1))
		glow.Visible = state.Box and state.Glow
		glow.ImageColor3 = state.BoxColor
		-- above the box: the weapon, then the name; a Top bar pushes them up
		local width = math.max(math.floor(state.HealthWidth), 1)
		local gap = math.max(math.floor(state.HealthGap), 0)
		local side = state.Health and state.HealthPos or nil
		local y = -2 - (side == "Top" and width + gap + 2 or 0)
		weapT.Visible = state.Weapon or EDIT
		weapT.TextTransparency, weapT.TextStrokeTransparency = state.Weapon and 0 or GHOST, state.Weapon and 0 or 1
		weapT.Text, weapT.TextSize, weapT.TextColor3 = tostring(state.WeaponText), state.FlagSize - 1, state.FlagColor
		weapT.Size = UDim2.fromOffset(160, state.FlagSize)
		weapT.Position = UDim2.new(0.5, 0, 0, y)
		if state.Weapon or EDIT then y -= state.FlagSize + 1 end
		nameT.Visible = state.Name or EDIT
		nameT.TextTransparency = state.Name and 0 or GHOST
		nameT.Text, nameT.TextSize, nameT.TextColor3 = tostring(state.NameText), state.NameSize, state.NameColor
		nameT.Size = UDim2.fromOffset(160, state.NameSize)
		nameT.TextStrokeTransparency = (state.Name and state.NameOutline) and 0.2 or 1
		nameT.TextStrokeColor3 = state.NameOutlineColor
		nameT.Position = UDim2.new(0.5, 0, 0, y)
		distT.Visible = state.Distance or EDIT
		distT.TextTransparency, distT.TextStrokeTransparency = state.Distance and 0 or GHOST, state.Distance and 0 or 1
		distT.Text, distT.TextSize, distT.TextColor3 = "[2m]", state.FlagSize - 1, white
		distT.Position = UDim2.new(0.5, 0, 1, 2 + (side == "Bottom" and width + gap + 2 or 0))
		-- the flags, right of the box (past a Right bar)
		local fx0 = 3 + (side == "Right" and width + gap + 4 + (state.HealthText and 18 or 0) or 0)
		for i, ln in state.FlagLines do
			local r = flagRows[i]
			if not r then
				r = text(12)
				r.TextXAlignment = Enum.TextXAlignment.Left
				flagRows[i] = r
				if EDIT then
					-- click an equipped flag to take it off
					local b = Instance.new("TextButton")
					b.Name = "\0"
					b.Text, b.AutoButtonColor, b.BackgroundTransparency, b.ZIndex = "", false, 1, 30
					b.Size = UDim2.new(0, 70, 1, 2)
					b.Parent = r
					Library:Connect(b.MouseButton1Click, function() if editHooks.toggleFlag and r:GetAttribute("Flag") then editHooks.toggleFlag(r:GetAttribute("Flag")) end end)
					Library.attachTooltip(b, "Click to remove this flag")
				end
			end
			r:SetAttribute("Flag", ln.name)
			r.Visible = true
			r.Text, r.TextSize, r.TextColor3 = tostring(ln.text), state.FlagSize - 1, ln.col or state.FlagColor
			r.Size = UDim2.fromOffset(120, state.FlagSize)
			r.Position = UDim2.new(1, fx0, 0, 1 + (i - 1) * (state.FlagSize + 1))
		end
		for i = #state.FlagLines + 1, #flagRows do flagRows[i].Visible = false end
		if editHooks.add then editHooks.add.Position = UDim2.new(1, fx0, 0, 1 + #state.FlagLines * (state.FlagSize + 1)) end
		hpBack.BackgroundColor3 = state.HealthOutlineColor
		hpBack.BackgroundTransparency = (not state.Health) and 0.85 or (state.HealthOutline == "None" and 1 or 0)
		hpBack.Visible = state.Health or EDIT
		hpFill.BackgroundTransparency = state.Health and 0 or GHOST
		hpT.TextSize = state.HealthTextSize - 1
		hpT.Size = UDim2.fromOffset(30, state.HealthTextSize)
		ringStroke.Color, edgeStroke.Color = state.LineColor, state.OutlineColor
		for i, l in bones do l.BackgroundColor3, boneEdges[i].BackgroundColor3 = state.LineColor, state.OutlineColor end
		lookLine.BackgroundColor3, lookTip.BackgroundColor3, lookEdge.BackgroundColor3 = state.LineColor, state.LineColor, state.OutlineColor
		paintChams()
	end
	local function layoutHealth(hp)
		if not state.Health then hpT.Visible = false return end
		local w = math.max(math.floor(state.HealthWidth), 1)
		local g = math.max(math.floor(state.HealthGap), 0)
		local pos, fit = state.HealthPos, state.HealthOutline == "Fit"
		local horizontal = pos == "Top" or pos == "Bottom"
		if horizontal then
			hpBack.AnchorPoint = Vector2.new(0, pos == "Top" and 1 or 0)
			hpBack.Position = UDim2.new(0, -1, pos == "Top" and 0 or 1, pos == "Top" and -g - 1 or g + 1)
			hpBack.Size = fit and UDim2.new(hp, 2, 0, w + 2) or UDim2.new(1, 2, 0, w + 2)
			hpFill.AnchorPoint, hpFill.Position = Vector2.zero, UDim2.fromOffset(1, 1)
			hpFill.Size = fit and UDim2.new(1, -2, 1, -2) or UDim2.new(hp, -2, 1, -2)
		else
			hpBack.AnchorPoint = Vector2.new(pos == "Right" and 0 or 1, fit and 1 or 0)
			hpBack.Position = UDim2.new(pos == "Right" and 1 or 0, pos == "Right" and g + 1 or -g - 1, fit and 1 or 0, fit and 1 or -1)
			hpBack.Size = fit and UDim2.new(0, w + 2, hp, 2) or UDim2.new(0, w + 2, 1, 2)
			hpFill.AnchorPoint, hpFill.Position = Vector2.new(0, 1), UDim2.new(0, 1, 1, -1)
			hpFill.Size = fit and UDim2.new(1, -2, 1, -2) or UDim2.new(1, -2, hp, -2)
		end
		local col = hpColor(hp)
		hpFill.BackgroundColor3 = col
		local showText = state.HealthText and not (state.HealthTextHideFull and hp >= 0.995)
		hpT.Visible = showText
		if showText then
			hpT.Text = tostring(math.floor(hp * 100))
			hpT.TextColor3 = state.HealthTextGradient and col or white
			local along = state.HealthTextFollow and (horizontal and hp or 1 - hp) or 0
			if horizontal then
				hpT.AnchorPoint = Vector2.new(0.5, pos == "Top" and 1 or 0)
				hpT.Position = UDim2.new(along, 0, pos == "Top" and 0 or 1, pos == "Top" and -g - w - 3 or g + w + 3)
			elseif pos == "Right" then
				hpT.AnchorPoint = Vector2.new(0, 0.5)
				hpT.Position = UDim2.new(1, g + w + 4, along, 0)
			else
				hpT.AnchorPoint = Vector2.new(1, 0.5)
				hpT.Position = UDim2.new(0, -g - w - 4, along, 0)
			end
		end
	end
	local preview = { Instance = root, State = state }
