				if cb then Library:SafeCall(cb, t) end
			end)
			fx.hover(b, function() if current ~= t then fx.tween(S.label, { TextColor3 = Library.Theme.Text }, 0.12) end end,
				function() if current ~= t then fx.tween(S.label, { TextColor3 = Library.Theme["Dim Text"] }, 0.15) end end)
		end
		Library.SetFlags.EspPreviewTarget = function(v)
			if items[v] and v ~= current then current = v Library.Flags.EspPreviewTarget = v paintTabs() loadTarget() end
