		local b = Instance.new("TextButton")
		b.Name = "\0"
		b.Text, b.AutoButtonColor, b.BackgroundTransparency = "", false, 1
		b.AnchorPoint, b.Position = Vector2.new(0.5, 0.5), UDim2.fromScale(0.5, 0.5)
		b.Size = UDim2.new(1, pad or 6, 1, pad or 6)
