			local function fit() b.Size = UDim2.fromOffset(math.max(lbl.TextBounds.X, 16) + 10, lbl.AbsoluteSize.Y + 4) end
			lbl:GetPropertyChangedSignal("TextBounds"):Connect(fit)
			fit()
		end
